(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0051","batch":"02","category":"Categoria B","question":"Sunteți obligat să circulați cu o viteză care să nu depășească 50 km/h în afara localităților, în următoarele situații:","answers":["La trecerea pe lângă animale care se deplasează pe partea carosabilă sau pe acostament","La circulația prin tunele","În zona pietonală, semnalizată ca atare"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul este obligat să circule cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților la trecerea pe lângă animale care sunt conduse pe partea carosabilă sau pe acostament. La circulația prin tunele rutiere nu aveți obligația să circulați cu o viteză care să nu depășească 50 km/h în afara localităților, însă trebuie să respectați regimul legal de viteză de pe respectivul sector de drum. În zonele pietonale semnalizate ca atare (Atenție! Nu în zona trecerilor pentru pietoni) veți circula cu o viteză care să nu depășească 5 km/h, fiindu-vă permisă intrarea numai dacă locuiți în acea zonă sau dacă prestați servicii publice „din poartă în poartă” și nu aveți altă posibilitate de acces, având obligația de a nu stânjeni sau împiedica circulația pietonilor și, dacă este necesar, să opriți pentru a permite circulația acestora","imageUrl":"/nivel-1/quiz-images/rodrive-all/0051.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0051.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 51; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 50 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sunteti-obligat-sa-circulati-cu-o-viteza-care-sa-nu-depaseasca-50-km-h-in-afara-localitatilor-in-urmatoarele-situatii","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"50","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0052","batch":"02","category":"Categoria B","question":"Neacordarea priorității înseamnă:","answers":["Nerespectarea semnificației semnalizării rutiere de obligare sau de avertizare","Nerespectarea dispozițiilor legale privind asigurarea și semnalizarea în intersecții","Obligarea celor care au prioritate de trecere de a-și modifica brusc direcția sau viteza de deplasare ori să oprească"],"correctIndices":[2],"correct":2,"explanation":"Neacordarea priorității de trecere înseamnă obligareacelor care au prioritate de trecerede a-și modifica brusc direcția sau viteza de deplasare ori să oprească. Cea mai des întâlnită situație de neacordare de prioritate se găsește în intersecțiile dirijate prin indicatoare de reglementare de prioritate, unde vehiculele care au obligația de a acorda prioritate de trecere nu respectă această obligație și îi obligă pe cei ce au prioritate de trecere să oprească pentru a evita producerea unui accident de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0052.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0052.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 52; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 51 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/neacordarea-prioritatii-inseamna","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"51","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0053","batch":"02","category":"Categoria B","question":"Pentru întreținerea sistemului de ungere, trebuie să efectuați:","answers":["Verificarea și completarea nivelului uleiului din baie","Înlocuirea uleiului după expirarea termenului de utilizare","Desfundarea orificiilor de aerisire ale radiatorului"],"correctIndices":[0,1],"correct":0,"explanation":"Pentru întreținerea sistemului de ungere trebuie să efectuați periodic verificarea și completarea nivelului uleiului din baia de ulei și sa înlocuiți în totalitate uleiul după expirarea termenului de utilizare. Prin termen de utilizare se înțelege termenul de valabilitate al acestuia sau numărul de km parcurși, acestea fiind diferite în funcție de tipul de ulei folosit sau de autovehicul. Controlul uleiului din baie se realizează cu ajutorul unei tije metalice numită jojă, care se introduce în blocul motor. Nivelul corect al uleiului în baie trebuie să fie între reperele minim și maxim însemnate pe joja de ulei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0053.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0053.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 53; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 52 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-intretinerea-sistemului-de-ungere-trebuie-sa-efectuati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"52","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0054","batch":"02","category":"Categoria B","question":"Cum veți parca regulamentar într-o piață cu sens giratoriu?","answers":["Paralel cu bordura trotuarului și cât mai aproape de aceasta","Parțial pe trotuar","În acest loc nu este permisă parcarea"],"correctIndices":[2],"correct":2,"explanation":"Parcarea se efectuează doar în spații special amenajate sau stabilite și semnalizate corespunzător. Pentru parcarea unui autovehicul este necesară manevra de oprire, iar oprirea voluntară a vehiculelor este interzisă în intersecții, inclusiv în cele cu circulație în sens giratoriu, precum și în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestora, la o distanță mai mică de 25 de metri de colțul intersecției.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0054.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0054.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 54; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 53 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-parca-regulamentar-intr-o-piata-cu-sens-giratoriu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"53","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0055","batch":"02","category":"Categoria B","question":"Vă apropiați de o intersecție fără indicatoare de circulație. Vizibilitatea în ambele direcții este imposibilă, din cauza vehiculelor staționate. Cum procedați?","answers":["Intrați încet în intersecție, cu atenție mărită","Traversați cât mai rapid intersecția","Semnalizați luminos și intrați în intersecție"],"correctIndices":[0],"correct":0,"explanation":"În intersecțiile nedirijate aveți obligația de a acorda prioritate vehiculelor care vin din partea dreaptă. Dacă vizibilitatea este foarte scăzută din cauza vehiculelor staționate (în majoritatea cazurilor acestea staționează neregulamentar, dar trebuie să fim pregătiți și pentru astfel de situații), trebuie să măriți atenția și să pătrundeți încet în intersecție pentru a vă oferi vizibilitatea necesara observării celorlalți participanți la trafic, iar dacă circulă alte vehicule din partea dreaptă, le acordați prioritate, daca nu, traversați ușor intersecția. Traversând cât mai repede intersecția este posibil să fiți surprins de un alt autovehicul pe care nu l­ați observat la timp și căruia să fi trebuit să îi acordați prioritate. Semnalizând luminos la intrarea în intersecție nu vă permite să intrați în intersecție fără să vă asigurați sau fără să acordați prioritate. Semnalizarea luminoasă, pentru a vă face simțită prezența, prin folosirea alternantă a luminilor de întâlnire cu cele de drum se folosește pe timpul nopții sau în condiții de vizibilitate redusă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0055.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0055.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 55; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 54 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/va-apropiati-de-o-intersectie-fara-indicatoare-de-circulatie-vizibilitatea-in-ambele-directii-este-imposibila-din-cauza-vehiculelor-stationa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"54","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0056","batch":"02","category":"Categoria B","question":"Conduceți autovehiculul / tractorul agricol sau forestier pe drumurile publice și refuzați recoltarea unor probe biologice în vederea stabilirii alcoolemiei. Veți fi pedepsit penal?","answers":["Da","Numai dacă sunteți implicat într-un accident de circulație","Nu"],"correctIndices":[0],"correct":0,"explanation":"Refuzul ori sustragerea conducătorului unui vehicul pentru care legea prevede obligativitatea deținerii permisului de conducere de a se supune prelevării de mostre biologice necesare în vederea stabilirii alcoolemiei ori a prezenței unor substanțe psihoactive este considerată infracțiune și se pedepsește cuînchisoarea de la unu la 5 aniși cu aplicarea măsurii de reținere a permisului de conducereîn vederea anulării acestuia.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0056.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0056.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 56; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 55 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conduceti-autovehiculul-tractorul-agricol-sau-forestier-pe-drumurile-publice-si-refuzati-recoltarea-unor-probe-biologice-in-vederea-stabilir","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"55","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0057","batch":"02","category":"Categoria B","question":"Polițistul rutier poate dispune imobilizarea unui vehicul atunci când:","answers":["Vehiculul nu are efectuată inspecția tehnică periodică","Anvelopele au alte dimensiuni decât cele prevăzute în cartea de identitate a vehiculului","Conducătorul auto refuză să se legitimeze"],"correctIndices":[2],"correct":2,"explanation":"Nu se imobilizează vehiculul dacă acesta nu are efectuată inspecția tehnică periodică (ITP) sau anvelopele au alte dimensiuni decât cele pentru care au fost omologate. Pentru aceste contravenții se reține certificatul de înmatriculare sau de înregistrare (talonul auto) ori dovada înlocuitoare a acestuia și se aplică amendă contravențională, conform articolelor din legislația rutieră actualizată la zi, ce se găsesc în această pagină, puțin mai jos. Imobilizarea unui vehicul se dispune de către polițistul rutier în cazul în care conducătorul acestuia refuză să se legitimeze. Pentru această contravenție se aplică, pe lângă imobilizarea vehiculului, amendă contravențională și puncte de penalizare, conform articolelor din legislația rutieră actualizată la zi, ce se găsesc în această pagina, puțin mai jos.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0057.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0057.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 57; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 56 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/politistul-rutier-poate-dispune-imobilizarea-unui-vehicul-atunci-cand","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"56","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0058","batch":"02","category":"Categoria B","question":"O hemoragie produsă la unul dintre membrele unei persoane rănite se va opri prin:","answers":["Dezinfectarea rănii, pansarea și aplicarea atelelor","Ridicarea membrului accidentat în poziție verticală","Acțiunea compresivă asupra vasului lezat sau aplicarea garoului"],"correctIndices":[2],"correct":2,"explanation":"Hemoragia poate fi externă, când sângele se scurge înafara corpului sau interna, când ruptura vasculară se produce în interiorul organismului (așa cum se întâmplă în fracturi sau în cazul rupturii unui organ) și se acumulează sângele în interiorul corpului. În cazul de față vorbim despre o hemoragie externă la unul dintre membre. Hemoragia produsă la unul dintre membrele unei persoane rănite se va opri prin:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0058.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0058.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 58; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 57 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/o-hemoragie-produsa-la-unul-dintre-membrele-unei-persoane-ranite-se-va-opri-prin","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"57","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0059","batch":"02","category":"Categoria B","question":"Cum procedați în prima intersecție?","answers":["Acordați prioritate de trecere tuturor vehiculelor care circulă în intersecție","Acordați prioritate de trecere numai vehiculelor care circulă din stânga","Aplicați regula priorității de dreapta"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul din imagine se numește „Intersecție de drumuri” și are rolul de a vă avertiza că urmează o intersecție nedirijată de două drumuri de aceeași categorie. La trecerea prin intersecțiile nedirijate aveți obligația de a circula cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților și să cedați trecerea vehiculelor care vin din partea dreaptă. Prin urmare, în prima intersecție aplicați regula priorității de dreapta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0059.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0059.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 59; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicatorul triunghiular roșu cu un X negru în mijloc, de avertizare, care indică faptul că urmează o intersecție nedirijată de două drumuri de aceeași categorie, unde se aplică regula priorității de dreapta.","needsImageReview":true,"source":"RoDrive · ID 58 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-prima-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"58","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_60.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0060","batch":"02","category":"Categoria B","question":"Aveți posibilitatea de a trece pe sensul opus de mers, la întâlnirea unui astfel de marcaj rutier?","answers":["Legal, nu este stabilit acest aspect","Da","Nu"],"correctIndices":[1],"correct":1,"explanation":"Marcajul longitudinal format dintr-o linie discontinuă, simplă sau dublă,permite trecerea peste acesta. Marcajul longitudinal format dintr-o linie continuă, simplă sau dublă,interziceîncălcarea acestuia. Însă atunci când marcajului longitudinal este format dintr-o linie continuă și una discontinuă alăturate, conducătorul de vehicultrebuie să respecte semnificația liniei celei mai apropiate în sensul de mers. Marcajul longitudinal din imagine este format dintr-o linie continuă și una discontinuă alăturate. Vă este permisă încălcarea acestui marcaj și trecerea pe sensul opus de mers deoarece linia discontinuă este cea mai apropiată de vehiculul pe care îl conduceți. Trebuie știut că, deși marcajul format dintr-o linie discontinuă simplă sau dublă permite trecerea peste acesta,o puteți face doar dacă manevra sau reglementările instituite impun acest lucru. De exemplu, se permite trecerea peste acesta la efectuarea manevrei de schimbare a benzii de circulație, la efectuarea manevrei de schimbare a direcției de mers sau la efectuarea manevrei de depășire.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0060.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0060.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 60; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu marcaj rutier longitudinal, care indică o linie continuă pe sensul opus și discontinuă pe sensul de mers. Aceasta permite depășirea, însă șoferul trebuie să se asigure că manevra este sigură și că nu există vehicule care vin din sens opus.","needsImageReview":true,"source":"RoDrive · ID 59 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/aveti-posibilitatea-de-a-trece-pe-sensul-opus-de-mers-la-intalnirea-unui-astfel-de-marcaj-rutier","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"59","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_61.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0061","batch":"02","category":"Categoria B","question":"Care dintre autovehicule va trece al doilea prin intersecția prezentată?","answers":["Autoturismul roșu","Autoturismul verde","Autocamionul"],"correctIndices":[1],"correct":1,"explanation":"Această intersecție este dirijată prin indicatoare de reglementare de prioritate. Pe drumul cu prioritate circulă autocamionul, deci va trece primul prin această intersecție. Între cele două autoturisme s-a creat o situație de egalitate, ambele venind de pe drumuri fără prioritate. Însă autoturismul roșu virând către stânga, trebuie să îi acorde prioritate autoturismului verde deoarece acesta îi vine din partea dreaptă. Deci al doilea prin această intersecție va trece autoturismul verde.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0061.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0061.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 61; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată cu indicatoare de prioritate. Vehiculul roșu vine din dreapta și intenționează să vireaze la stânga, având în dreptul său indicatorul triunghiular cu margine roșie, 'Cedează Trecerea', ce impune cedarea trecerii celorlalte vehicule. Vehiculul albastru, care pătrunde de jos, nu are indicator în față și merge înainte. Vehiculul verde, care vine din dreapta și merge în față are în față un indicator octogonal roșu, pe care scrie STOP cu alb, ce îi impune să oprească și să cedeze trecerea celorlalte vehicule.","needsImageReview":true,"source":"RoDrive · ID 60 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-autovehicule-va-trece-al-doilea-prin-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"60","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_62.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0062","batch":"02","category":"Categoria B","question":"Indicatorul vă avertizează că urmează:","answers":["O coborâre periculoasă, care începe la o distanță de 200 m de la indicator","O coborâre periculoasă, pe o distanță de 200 m","O succesiune de curbe periculoase, la o distanță de 200 m de la indicator"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Coborâre periculoasă” și vă avertizează despre existența unei pante cu inclinare de 7,5%. Panoul adițional se numește „Distanța între indicator și începutul locului periculos” și vă informează despre distanța la care începe coborârea față de indicator. Deci indicatorul împreună cu panoul adițional vă avertizează că peste 200 de metri de indicator urmează o coborâre periculoasă. Deși prin aplicarea normelor de conduită preventivă se ajunge la micșorarea vitezei, prin lege, nu este obligatorie reducerea vitezei. Este interzisă staționarea pe toată lungimea pantei, iar în vârful acesteia, când vizibilitatea este redusă sub 50 de metri, toate manevrele sunt interzise.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0062.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0062.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 62; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum acoperit cu zăpadă și un indicator triunghiular roșu, cu un simbol negru care reprezintă o pantă cu înclinare abruptă, însoțit de inscripția „7.5%” care avertizează asupra unei pante abrupte de 7.5%, însoțit de un panou adițional dreptunghiular, pe care scrie 200, arătând că această pantă urmează în 200 de metri.","needsImageReview":true,"source":"RoDrive · ID 61 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-va-avertizeaza-ca-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"61","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_63.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0063","batch":"02","category":"Categoria B","question":"Autovehiculul din fața dvs. traversează intersecția. Cum veți proceda?","answers":["Executați aceeași manevră, dacă nu sunt alte obligații","Opriți, deoarece trebuie să vă asigurați","Cedați trecerea autovehiculelor care vin din dreapta"],"correctIndices":[0],"correct":0,"explanation":"La efectuarea oricărei manevre trebuie să vă asigurați că aceasta este permisă și că se poate executa în condiții de siguranță, nu trebuie să contați sau să vă lăsați influențați de manevrele pe care le face conducătorul vehiculului din față. Prin urmare, în această situație trebuie să vă asigurați dacă semnalul semaforului vă permite să intrați în intersecție. Semnalul semaforului pentru direcția înainte este verde, deci puteți traversa intersecția.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0063.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0063.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 63; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată din perspectiva unui șofer. Sunt două semafoare în dreptul șoferului. Semaforul din dreapta, verde, cu un panou adițional cu o săgeată neagră în sus, permite deplasarea înainte, iar cel roșu, din stânga, cu panou adițional cu o săgeată neagră în stânga interzice deplasarea la stânga, conform indicatorelor adiționale de sub ele. Șoferul se află pe banda din dreapta, marcată cu o săgeată albă in sus, ce impune șoferului deplasarea înainte. În fața lui se află o mașina care circulă în față, regulamentar.","needsImageReview":true,"source":"RoDrive · ID 62 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autovehiculul-din-fata-dvs-traverseaza-intersectia-cum-veti-proceda","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"62","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_64.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0064","batch":"02","category":"Categoria B","question":"Vă este permis să claxonați un biciclist înainte de a-l depăși?","answers":["Da, dacă distanța este de peste 25 m","Nu","Numai în reprize foarte scurte"],"correctIndices":[0],"correct":0,"explanation":"Regulamentul rutier specifică faptul că mijloacele de avertizare sonoră trebuie folosite de la o distanță de cel puțin 25 de metri față de cei cărora li se adresează. Prin urmare, vă este permisă claxonarea bicicliștilor înainte să îi depășiți dacă distanța până la aceștia este mai mare de 25 de metri. Avertizarea sonoră a bicicliștilor, folosind claxonul, este recomandată înaintea depășirii acestora din punct de vedere preventiv, dar această avertizare trebuie să se facă de la o distanță și pe o durată care să nu-i sperie sau să nu-i determine pe aceștia la manevre imprudente și să fie, așa cum specifică și regulamentul rutier, mai mare de 25 de metri. Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încă","imageUrl":"/nivel-1/quiz-images/rodrive-all/0064.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0064.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 64; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație din perspectiva unui șofer pe un drum rural, unde un biciclist circulă pe marginea drumului, aproape de șofer.","needsImageReview":true,"source":"RoDrive · ID 63 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/va-este-permis-sa-claxonati-un-biciclist-inainte-de-a-l-depasi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"63","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_65.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0065","batch":"02","category":"Categoria B","question":"În ce ordine vor trece prin intersecție cele patru autovehicule?","answers":["Autoturismul, autocamionul, motocicleta, autobuzul","Autobuzul, autocamionul, motocicleta, autoturismul","Autoturismul, autobuzul, motocicleta, autocamionul"],"correctIndices":[2],"correct":2,"explanation":"Această intersecție este dirijată prin indicatoare de reglementare de prioritate. Autocamionul și motocicleta vin de pe drumuri fără prioritate și trebuie să le acorde prioritate autobuzului și autoturismului. Deci pe drumul cu prioritate circulă autobuzul și autoturismul. Între aceștia s-a creat o situație de egalitate, ambii întâlnind indicatorul „Drum cu prioritate”. Însă autobuzul trebuie să îi acorde prioritate de trecere autoturismului, deoarece schimbând direcția de deplasare spre stânga, pierde prioritatea față de autoturism. Deci primul trece autoturismul iar al doilea trece autobuzul. De asemenea, între motocicletă și autocamion s-a creat o situație de egalitate, însă autocamionul virând către stânga pierde prioritatea față de motocicletă. Deci a treia va trece motocicleta și ultimul va trece autocamionul. Prin urmare ordinea de trecere este următoarea: autoturismul, autobuzul, motocicleta, autocamionul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0065.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0065.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 65; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea reprezintă o intersecție cu patru ramuri, văzută de sus, în care circulă patru vehicule: o motocicletă, un autoturism, un autobuz și un camion. Fiecare vehicul are o săgeată colorată ce indică intenția de deplasare. Motocicleta (stânga) dorește să meargă înainte, autoturismul (sus) merge înainte, autobuzul (jos) virează la stânga, iar camionul (dreapta) virează la stânga. Fiecare drum are un indicator rutier vizibil în partea dreaptă a fiecărui vehicul: autoturismul și autobuzul se află pe drumuri cu prioritate (indicatoare galbene în formă de romb), motocicleta are un indicator de 'cedează trecerea', iar camionul are un indicator STOP.","needsImageReview":true,"source":"RoDrive · ID 64 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-trece-prin-intersectie-cele-patru-autovehicule","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"64","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_66.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0066","batch":"02","category":"Categoria B","question":"Trecerea peste marcajul discontinuu este permisă:","answers":["În orice situație, acesta având un caracter orientativ","Atunci când un asemenea marcaj nu delimitează cele două sensuri de circulație","La schimbarea benzii de circulație, a direcției de mers sau la depășire"],"correctIndices":[2],"correct":2,"explanation":"Marcajul longitudinal format dintr-o linie discontinuă simplă sau dublă permite trecerea peste acesta tuturor conducătorilor de vehicule, indiferent de direcția din care aceștia circulă și indiferent dacă marcajul separă sensurile de circulație sau separă benzile de pe același sens de circulație. Chiar dacă marcajul format dintr-o linie discontinuă simplă sau dublă permite trecerea peste acesta,o puteți face doar dacă manevra sau reglementările instituite impun acest lucru. De exemplu, se permite trecerea peste acesta la efectuarea manevrei de schimbare a benzii de circulație, la efectuarea manevrei de schimbare a direcției de mers sau la efectuarea manevrei de depășire.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0066.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0066.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 66; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 65 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/trecerea-peste-marcajul-discontinuu-este-permisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"65","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0067","batch":"02","category":"Categoria B","question":"Cum trebuie să semnalizați intenția de a depăși alte vehicule, atunci când conduceți vehiculul noaptea, pe un drum neiluminat dintr-o localitate?","answers":["Cu luminile farurilor","Prin folosirea luminii de drum sau a claxonului","Cu luminile indicatoare de direcție"],"correctIndices":[2],"correct":2,"explanation":"Nu este permisă folosirea luminilor farurilor sau a claxonului pentru a semnaliza intenția de a depăși alte vehicule. Luminile de drum (faza lungă) nu se va folosi pe timp de noapte de la mai puțin de 100 de metri față de vehiculul carecirculă în fața Dvs. în același sensși de la mai puțin de 200 de metri față de vehiculul carecirculă din sens opus. Se interzice conducătorului de autovehicul sau de tramvai să folosească în mod abuziv mijloacele de avertizare sonoră. Mijloacele de avertizare sonoră trebuie folosite de la o distanță de cel puțin 25 de metri față de cei cărora li se adresează, pe o durată de timp care să asigure perceperea semnalului și fără să îi determine pe aceștia la manevre ce pot pune în pericol siguranța circulației. Indiferent dacă circulați pe timp de zi sau de noapte sau indiferent de împrejurări, intenția de a depăși alte vehicule se semnalizează doar cu luminile indicatoare de direcție. Nu se va folosi nici un alt tip de semnalizare pentru semnalizarea intenției de a depăși alte vehicule.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0067.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0067.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 67; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 66 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-semnalizati-intentia-de-a-depasi-alte-vehicule-atunci-cand-conduceti-vehiculul-noaptea-pe-un-drum-neiluminat-dintr-o-localita","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"66","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0068","batch":"02","category":"Categoria B","question":"În ce situații este interzisă depășirea unei biciclete?","answers":["În zona de acțiune a indicatorului „depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă“","Pe trecerile de pietoni semnalizate","La mai puțin de 100 m de trecerea la nivel cu calea ferată"],"correctIndices":[1],"correct":1,"explanation":"În zona de acțiune a indicatorului “Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă” vă este permisă depășirea motocicletelor fără ataș și a vehiculelor simple, ca de exemplu bicicletele. Se interzice depășirea tuturor vehiculelor pe trecerile pentru pietoni semnalizate prin indicatoare și marcaje. Deci se interzice și depășirea bicicletelor pe trecerile pentru pietoni. Vă este permis să depășiți biciclete și la mai puțin de 100 de metri de o trecere la nivel cu o cale ferată, deoarece depășirea vă este interzisă pe trecerile la nivel cu calea ferată și la mai puțin de 50 de metri înainte de acestea. Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încălcarea sau trecerea peste a","imageUrl":"/nivel-1/quiz-images/rodrive-all/0068.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0068.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 68; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 67 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-situatii-este-interzisa-depasirea-unei-biciclete","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"67","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0069","batch":"02","category":"Categoria B","question":"Ce obligații aveți înainte de efectuarea unei depășiri?","answers":["Să semnalizați intenția și să efectuați depășirea","Să vă asigurați din față și să reduceți corespunzător viteza","Să vă asigurați și să semnalizați intenția de depășire"],"correctIndices":[2],"correct":2,"explanation":"Atunci când doriți să efectuați manevra de depășire, aveți următoarele obligații: Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încălcarea sau trecerea peste acest marcaj cu linie continuă, iarpentru depășirea acestor vehicule este obligatorie încălcarea sau trecerea peste acest marcaj. Singura opțiune, regulamentară, este de a merge în spatele acestor vehicule până la terminarea marcajului cu line continuă și începerea marcajului cu linie discontinuă care se poate încălca și se poate efectua regulamentar depășirea acestor vehicule. Aceste prevederi legislative legate de depășirea bicicletelor sau trotinetelor electrice au fost adăugate în 2021 în legislația rutiera.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0069.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0069.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 69; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 68 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-inainte-de-efectuarea-unei-depasiri","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"68","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0070","batch":"02","category":"Categoria B","question":"Sunteți obligat să reduceți viteza până la limita legală la trecerile pentru pietoni nesemaforizate, dar semnalizate prin indicatoare și marcaje, dacă:","answers":["Drumul are cel mult o bandă pe sens, iar pietonii aflați pe trotuar intenționează să se angajeze în traversare","Drumul are cel puțin două benzi pe sens","Trecerile sunt localizate în dreptul stațiilor de tramvai"],"correctIndices":[0],"correct":0,"explanation":"La trecerile pentru pietoninesemaforizate,semnalizate prin indicatoare și marcaje, când drumul public areo singură bandă de circulație pentru fiecare sens, se procedează după cum urmează: Trebuie reținut că legislația rutieră impune această obligație de a circula cu o viteza care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților dacă trecerea pentru pietoni care estenesemaforizată, semnalizată prin indicatoare și marcaje,se afla pe un drum cu o singură bandă de circulație pe sens, iar pietonii aflați pe trotuar, în imediată apropiere a părții carosabile, intenționează să se angajeze în traversare.În cazul în care drumul are două sau mai multe benzi de circulație pe sens, această obligație privind viteza de deplasarenu se mai aplică, indiferent dacă se află pietoni în imediata apropiere a trecerii pentru pietoni care intenționează să se angajeze în traversare, însă rămâne obligația de a acorda prioritate pietonilor, atunci când aceștia se află pe sensul dumneavoastră de mers. Mai multe informații despre obligațiile pe care le are conducătorul de vehicul la trecerea pentru pietoni, în funcție de tipul acesteia și de numărul de benzi pe sens, găsiți în lecția Audio-Video „Capitolul 4 partea 2 - Trecerea pentru pietoni și obligațiile pietonilor” din pasul 1 de pe Școala Rutieră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0070.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0070.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 70; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 69 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sunteti-obligat-sa-reduceti-viteza-pana-la-limita-legala-la-trecerile-pentru-pietoni-nesemaforizate-dar-semnalizate-prin-indicatoare-si-marc","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"69","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0071","batch":"02","category":"Categoria B","question":"Bicicliștii și conducătorii de vehicule cu tracțiune animală sunt obligați să acorde întotdeauna prioritate?","answers":["Da, deoarece viteza de deplasare este mică","Da, dacă circulă pe drumuri județene sau comunale","Nu, dacă semnalizarea rutieră nu prevede acest lucru"],"correctIndices":[2],"correct":2,"explanation":"Bicicliștii și conducătorii de vehicule cu tracțiune animalăNU au obligația să acorde întotdeauna prioritate, aceștia, ca și ceilalți participanți la trafic, trebuie să respecte regulile de circulație, indicatoarele, marcajele și semnalele polițistului rutier în aceeași măsură ca și autovehiculele. Prin urmare, dacă un biciclist sau un conducător de vehicul cu tracțiune animală circulă pe un drum prioritar, acesta nu are obligația să acorde prioritate autovehiculelor care circulă pe drumul fără prioritate. Acestea vor acorda prioritate doar când semnalizarea rutieră sau regulile de circulație prevăd acest lucru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0071.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0071.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 71; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 70 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/biciclistii-si-conducatorii-de-vehicule-cu-tractiune-animala-sunt-obligati-sa-acorde-intotdeauna-prioritate","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"70","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0072","batch":"02","category":"Categoria B","question":"Purtarea centurii de siguranță nu este obligatorie în localități pentru:","answers":["Copiii cu vârsta de până la 12 ani","Persoanele care posedă un document în acest sens, emis de o instituție medicală de specialitate","Femeia care prezintă o sarcină vizibilă"],"correctIndices":[1,2],"correct":1,"explanation":"Conducătorii de autovehicule și tractoare agricole sau forestiere și persoanele care ocupă locuri prevăzute prin construcție cu centuri sau dispozitive de siguranță omologatetrebuie să le poarte în timpul circulației pe drumurile publice, indiferent dacă ocupă locurile din față sau din spate ale autovehiculului și indiferent dacă circulă în localitate sau în afara localității. Conducătorii de autovehicule având locuri prevăzute prin construcție cu centuri de siguranță trebuie să informeze pasagerii cu privire la obligația legală de a le purta în timpul circulației pe drumurile publice. Cu toate acestea, legislația rutieră prevede anumite excepții de la obligația de a purta centura de siguranță, printre excepții se află persoanele care au certificat medical în care să fie menționată afecțiunea care contraindică purtarea centurii de siguranță, precum și femeile în stare vizibilă de graviditate, aceste două categorii fiind scutite de la această obligație. Legislația rutierăNUprevede o excepție de la purtarea centurii de siguranță pentru copiii cu vârsta de până la 12 ani. În cazul transportului de copii în autovehicule, legislația rutieră este foarte strictă, pentru aceștia sunt obligații speciale ce trebuie bine înțelese. Pentru mai multe informații cu privire la regulile ce trebuie respectate la transportarea copiilor accesați lecția Audio-Video „Capitolul 8 partea 7 - Obligații și interdicții privind transportul copiilor” din pasul 1 de pe Școala Rutieră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0072.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0072.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 72; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 71 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/purtarea-centurii-de-siguranta-nu-este-obligatorie-in-localitati-pentru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"71","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0073","batch":"02","category":"Categoria B","question":"Este permisă staționarea în dreptul căilor de acces care deservesc proprietățile alăturate drumurilor publice?","answers":["Legal, nu este prevăzut","Da, dar numai a autovehiculelor având o masă totală maximă autorizată de până la 1,5 t","Nu, deoarece staționarea în astfel de locuri este interzisă"],"correctIndices":[2],"correct":2,"explanation":"Staționarea voluntară a vehiculelor este interzisă în dreptul căilor de acces care deservesc proprietățile alăturate drumurilor publice, indiferent de masa totală maximă autorizată a acestora.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0073.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0073.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 73; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 72 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-stationarea-in-dreptul-cailor-de-acces-care-deservesc-proprietatile-alaturate-drumurilor-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"72","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0074","batch":"02","category":"Categoria B","question":"Ce pericole pot apărea prin nefolosirea centurii de siguranță?","answers":["Chiar și la o viteză de coliziune de aproximativ 20 km/h, există riscul unei accidentări","Pericolele pot apărea la o viteză de peste 60 km/h","Pericolul de accidentare este exclus"],"correctIndices":[0],"correct":0,"explanation":"Chiar și în cazul unei coliziuni la o viteză de 20km/h pot fi cauzate accidentări dacă pasagerii sau conducătorul vehiculului nu poartă centură de siguranță, aceștia se pot lovi de părțile dure ale vehiculului (bord, parbriz, volan). Rolul centurii de siguranță este acela de a proteja pasagerul sau conducătorul de vehicul împotriva accidentărilor. Fiind flexibilă, centura de siguranță încetinește viteza cu care vă deplasați către înainte, împiedicând să vă loviți de părțile dure ale vehiculului sau, în cazul în care vă loviți, riscul de accidentare este mult mai scăzut. Trebuie știut că persoanele care ocupă locuri prevăzute cu centuri de siguranță sunt obligate să le poarte în timpul deplasării.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0074.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0074.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 74; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 73 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-pericole-pot-aparea-prin-nefolosirea-centurii-de-siguranta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"73","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0075","batch":"02","category":"Categoria B","question":"Punctele de penalizare se aplică pentru:","answers":["Nerespectarea semnificației indicatorului „copii“","Nerespectarea semnificației indicatorului „drum cu denivelări“","Nerespectarea semnificației indicatorului „oprire“, instalat la trecerea la nivel cu o cale ferată"],"correctIndices":[2],"correct":2,"explanation":"Pentru nerespectarea semnificației indicatoarelor „Copii” și „Drum cu denivelări” se aplică amenda contravențională prevăzută în clasa a III-a de sancțiuni, fără să se aplice și puncte de penalizare. Atunci când vă apropiați de o trecere la nivel cu o cale ferată curentă și întâlniți unul dintre indicatoarele „Trecere la nivel cu o cale ferată simplă, fără bariere”, „Trecere la nivel cu o cale ferată dubla, fără bariere” sau „Oprire”, aveți obligația de a opri în locul cu vizibilitate maximă asupra căii ferate, fără a trece de indicatoare și să vă asigurați că din partea stângă sau din partea dreaptă nu se apropie niciun vehicul feroviar, după care vă puteți continua deplasarea. Nerespectarea acestei obligații constituie contravenție și se sancționează cu amenda contravențională prevăzută în clasa a IV-a de sancțiuni și cu aplicarea a 6 puncte de penalizare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0075.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0075.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 75; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 74 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/punctele-de-penalizare-se-aplica-pentru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"74","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0076","batch":"02","category":"Categoria B","question":"În ce situație se interzice circulația autovehiculelor pe drumurile publice?","answers":["Când plăcuțele cu numărul de înmatriculare sunt neconforme cu standardul","Când parbrizul prezintă fisuri","Când acestea au montate dispozitive de detectare a prezenței aparatelor radar"],"correctIndices":[0],"correct":0,"explanation":"Conducătorului de autovehicul îi este interzis să circule cu autovehiculul având placuțele cu numerele de înmatriculare sau de înregistrare deteriorate sau neconforme cu standardul. Dacă acestea sunt deteriorate veți fi sancționat cu amendă contravențională prevăzută în clasa I de sancţiuni. Dacă acestea sunt neconforme cu standardul se vor reține placuțele cu numerele, se va reține certificatul de înmatriculare sau de înregistrare, vehiculul se va imobiliza și se va aplica și amendă contravențională plus puncte de penalizare. Nu este interzisă circulația vehiculelor dacă parbrizul acestora prezintă fisuri. Nu este interzisă circulația dacă acestea au montate dispozitive de detectare a prezenței aparatelor radar, aceste dispozitive fiind legale. Aici trebuie să facem diferența între „dispozitivede detectarea prezenței aparatelor radar”, adicădetectoare de radar, care sunt permise, și „dispozitivelecare perturbăfuncţionarea mijloacelor tehnice de supraveghere a traficului”, adică aparateleANTI-radar, care sunt interzise.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0076.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0076.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 76; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 75 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-situatie-se-interzice-circulatia-autovehiculelor-pe-drumurile-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"75","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0077","batch":"02","category":"Categoria B","question":"Care sunt criteriile de apreciere a eficacității frânelor?","answers":["Spațiul de frânare","Forma pedalei","Mărimea urmei de frânare imprimată pe carosabil"],"correctIndices":[0],"correct":0,"explanation":"Criteriul de apreciere a eficacității frânelor este determinat de spațiul de frânare. Cu cât spațiul de frânare este mai mic, cu atât frânele sunt mai eficace. Iar spațiul de frânare depinde cel mai mult de viteza cu care se deplasează autovehiculul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0077.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0077.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 77; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 76 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-sunt-criteriile-de-apreciere-a-eficacitatii-franelor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"76","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0078","batch":"02","category":"Categoria B","question":"Cum trebuie să se încadreze conducătorul de autovehicul, dacă intenționează să schimbe direcția de mers spre stânga într-o intersecție prin care circulă și tramvaie, iar spațiul dintre șina din dreapta și bordura trotuarului permite deplasarea vehiculelor doar pe un singur rând?","answers":["Pe linia tramvaiului","Pe singurul rând rămas la dispoziție, lăsând liber traseul tramvaiului","În această situație nu se poate schimba direcția de mers spre stânga"],"correctIndices":[1],"correct":1,"explanation":"Conducătorul de autovehicul care intenționează să schimbe direcția de mers spre stânga într-o intersecție prin care circulă și tramvaie, iar spațiul dintre șina din dreapta și bordura trotuarului permite deplasarea vehiculelor doar pe un singur rând, se va încadra pe singurul rând rămas la dispoziția sa, fără a ocupa traseul tramvaiului. Atragem atenția că întrebarea se referă la intersecțiile fără marcaje de delimitare a benzilor, mai exact când sensul de mers are o singură bandă, pe care se află amplasată și lina tramvaiului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0078.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0078.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 78; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 77 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-se-incadreze-conducatorul-de-autovehicul-daca-intentioneaza-sa-schimbe-directia-de-mers-spre-stanga-intr-o-intersectie-prin-c","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"77","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0079","batch":"02","category":"Categoria B","question":"Inspecția tehnică periodică a autovehiculelor / tractoarelor agricole sau forestiere și a remorcilor trebuie efectuată:","answers":["Anual, la orice service auto","Periodic, conform legii","La cel mult doi ani, la o stație de inspecție tehnică autorizată"],"correctIndices":[1],"correct":1,"explanation":"Pentru a fi menținute în circulație, vehiculele înmatriculate se supun inspecției tehnice periodice. Inspecția tehnică periodică se efectuează în stații autorizate, conform legislației în vigoare. Pentru autovehicule inspecția tehnică periodică se efectuează la diferite intervale de timp în funcție de tipul de autovehicul, de exemplu la AUTOTURISME normale trebuie efectuată din doi în doi ani iar la autovehiculele destinate transportului de mărfuri, având o masa totală maxima autorizata mai mare de 3.500 kg, din an în an, DAR AMBELE SUNT AUTOVEHICULE. Consultați articolul de referință pentru mai multe detalii!","imageUrl":"/nivel-1/quiz-images/rodrive-all/0079.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0079.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 79; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 78 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/inspectia-tehnica-periodica-a-autovehiculelor-tractoarelor-agricole-sau-forestiere-si-a-remorcilor-trebuie-efectuata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"78","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0080","batch":"02","category":"Categoria B","question":"Cum se sancționează depășirea pe partea dreaptă a sensului de mers, fără semnalizare și încadrare corespunzătoare direcției de deplasare?","answers":["Cu amendă contravențională și puncte de penalizare","Cu amendă contravențională","Cu amendă contravențională și suspendarea exercitării dreptului de a conduce autovehiculul"],"correctIndices":[2],"correct":2,"explanation":"Depășirea se efectuează numai pe partea stângă a vehiculului depășit. Tramvaiul sau vehiculul al cărui conducător a semnalizat intenția și s-a încadrat corespunzător părăsirii sensului de mers spre stânga se depășește prin partea dreapta. Nerespectarea regulilor privind depășirea, ca de exemplu depășirea pe partea dreaptă a sensului de mers, fără semnalizare și încadrare corespunzătoare, constituie contravenție și se sancționează cu amenda prevăzută în clasa a III-a de sancțiuni și cu suspendarea exercitării dreptului de a conducepentru o perioadă de 60 de zile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0080.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0080.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 80; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 79 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-sanctioneaza-depasirea-pe-partea-dreapta-a-sensului-de-mers-fara-semnalizare-si-incadrare-corespunzatoare-directiei-de-deplasare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"79","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0081","batch":"02","category":"Categoria B","question":"Când este obligat conducătorul unui vehicul să oprească?","answers":["La semnalul conducătorului grupurilor organizate","La semnalul patrulelor școlare de circulație la trecerile pentru pietoni din apropierea unităților școlare","Când se apropie de o intersecție sau când este semnalizat cu farurile de un alt participant la trafic"],"correctIndices":[1],"correct":1,"explanation":"Conducătorul de vehiculNUare obligația să oprească la semnalul conducătorului grupurilor organizate. Însăla trecerea pe lângă grupuri organizate, indiferent dacă acestea se află în mers sau staționează pe partea carosabilă a drumurilorcu o singură bandă de circulație pe sens, conducătorul de vehicul este obligat să circule cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților. Conducătorul de vehiculeste obligatsă oprească la semnalele date de membrii patrulelor școlare de circulație, la trecerile pentru pietoni din apropierea unităților de învățământ. Conducătorul de vehiculNUare obligația să oprească întotdeauna când se apropie de intersecție. Un exemplu de intersecție în carenu este obligatorie oprireaeste cea la care conducătorul de vehicul întâlnește indicatorul „Drum cu prioritate”, iar un exemplu de intersecție în careeste obligatorie oprireaeste cea la care conducătorul de vehicul întâlnește indicatorul „Oprire”, indicator care obligă la oprire pentru asigurare, indiferent de situație. De asemenea, conducătorul de vehicul nu are obligația să oprească nici când este semnalizat cu farurile de un alt participant la trafic.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0081.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0081.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 81; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 80 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-este-obligat-conducatorul-unui-vehicul-sa-opreasca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"80","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0082","batch":"02","category":"Categoria B","question":"Ce înseamnă să conduceți preventiv pe timp nefavorabil?","answers":["Să respectați cu strictețe limitele de viteză pentru sectorul de drum pe care circulați","Să reduceți viteza până la limita la care să vă asigurați o bună vizibilitate și un control deplin asupra comenzilor","Să rulați cât mai aproape de axul drumului"],"correctIndices":[1],"correct":1,"explanation":"Respectarea cu strictețe a limitelor de viteză pentru sectorul de drum pe care circulați nu este parte a conduitei preventive, ci o obligație din punct de vedere legal. Conducătorii de vehicule trebuie să adapteze viteza de deplasare până la limita la care să se asigure o bună vizibilitate și control deplin asupra comenzilor autovehiculului. De exemplu, dacă circulăm în localitate pe timp de ploaie torențială, avem obligația de a circula cu maxim 30 de km/h, dar sunt situații în care chiar si 30 km/h este o viteză mare, astfel trebuie redusă viteza până la limita la care să vă asigurați o bună vizibilitate și un control deplin asupra comenzilor. Se recomandă, din punct de vedere al conduitei preventive dar și din punct de vedere legal, menținerea unei distanțe laterale suficientă față de vehiculele care circulă din sens opus. Prin urmare, nu este corect să rulați cât mai aproape de axul drumului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0082.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0082.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 82; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 81 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-inseamna-sa-conduceti-preventiv-pe-timp-nefavorabil","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"81","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0083","batch":"02","category":"Categoria B","question":"La întâlnirea unui vehicul greu cu unul ușor, pe un drum public îngust, pentru a face posibilă trecerea va manevra cu spatele:","answers":["Vehiculul ușor","Vehiculul greu","La libera înțelegere"],"correctIndices":[0],"correct":0,"explanation":"În situația în care un vehicul greu și unul ușor se întâlnesc pe un drum public îngust, iar trecerea ambelor vehicule, unul pe lângă celălalt, este imposibilă sau periculoasă, conducătorul vehiculului ușor va manevra cu spatele pentru a face posibilă trecerea vehiculului greu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0083.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0083.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 83; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 82 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-intalnirea-unui-vehicul-greu-cu-unul-usor-pe-un-drum-public-ingust-pentru-a-face-posibila-trecerea-va-manevra-cu-spatele","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"82","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0084","batch":"02","category":"Categoria B","question":"La intersecția nedirijată dintre un drum județean și unul comunal sau local, prioritatea de trecere se acordă:","answers":["Vehiculelor care circulă pe drumul județean","Vehiculelor care circulă pe drumul comunal sau local","Vehiculelor care vin din dreapta"],"correctIndices":[0],"correct":0,"explanation":"La intersecțianedirijată a două drumuri de categorii diferitenu se aplică regula priorității de dreapta, se va acorda prioritate vehiculelor care circulă pe „drumul superior”. Regula priorității de dreapta se va aplica în intersecția nedirijată dacă drumurile care se intersectează sunt de aceeași categorie (de exemplu două drumuri comunale sau două străzi dintr-un oraș). Dacă drumurile care se intersectează sunt de categorii diferite se va acorda prioritate vehiculelor care circulă pe „drumul superior”. Prin urmare, la intersecția nedirijată dintre un drum județean și unul comunal sau local, prioritate de trecerea se acordă vehiculelor care circulă pe drumul județean.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0084.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0084.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 84; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 83 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-intersectia-nedirijata-dintre-un-drum-judetean-si-unul-comunal-sau-local-prioritatea-de-trecere-se-acorda","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"83","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0085","batch":"02","category":"Categoria B","question":"Comportamentul ecologic în conducerea unui autovehicul presupune:","answers":["Planificarea traseului pentru a economisi timp și combustibil","Evitarea zonelor cu circulație densă, cu lucrări pe carosabil sau cu teren accidentat","Viteză și accelerație mai mari, pentru a scurta timpul de deplasare"],"correctIndices":[0,1],"correct":0,"explanation":"Planificarea traseului pentru a economisii atât timp cât și carburant face parte din comportamentul conducerii ecologice, de asemenea evitarea zonelor aglomerate este tot un comportament ecologic. Mărirea vitezei și a accelerației pentru scurtarea timpului de deplasare nu reprezintă o conduită ecologică. În schimb, pentru a reduce consumul de combustibil este recomandat să folosiți o viteză constantă, de preferat medie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0085.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0085.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 85; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 84 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/comportamentul-ecologic-in-conducerea-unui-autovehicul-presupune","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"84","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0086","batch":"02","category":"Categoria B","question":"Se interzice oprirea voluntară:","answers":["La mai puțin de 100 m de calea ferată industrială","Pe trotuar","În zona de acțiune a indicatorului „prioritate față de circulația din sens invers\""],"correctIndices":[2],"correct":2,"explanation":"Nu vă este interzis să opriți la mai puțin de 100 de metri de calea ferată industrială, oprirea fiind interzisă pe platforma căii ferate industriale sau de tramvai ori la mai puțin de 50 m de acestea, dacă circulația vehiculelor pe șine ar putea fi stânjenită sau împiedicată. Oprirea este permisă pe trotuar, în locurile semnalizate ca atare, mai exact dacă administratorul drumului public a executat pe anumite zone ale trotuarului amenajări destinate opririi sau staționării vehiculelor. Administratorul trebuie să respecte culoarul destinat circulației pietonilor, care nu poate fi mai mic de 1 m lățime. Trebuie ținut cont că în locurile în care se permite oprirea/staționarea/parcareape trotuar, legislația rutieră interzice aceste manevre dacă respectivul vehicul, prin dimensiunile lui, nu poate fi poziționat astfel încât porțiunea din lățimea trotuarului care rămâne la dispoziția circulației pietonilor să fie de cel puțin un metru. Pe sectoarele de drum unde este instalat indicatorul „Prioritate pentru circulația din sens invers” sau indicatorul „Prioritate față de circulația din sens invers” se interzice oprirea voluntară a vehiculelor. Aceeași interzicere se aplică și pe sectoarele de drum unde este instalat indicatorul „Drum îngustat”, chiar dacă sunt sau nu instalate și indicatoarele de reglementare de prioritate de mai sus.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0086.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0086.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 86; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 85 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/se-interzice-oprirea-voluntara","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"85","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0087","batch":"02","category":"Categoria B","question":"Cum trebuie să procedați atunci când un autobuz școlar oprește cu luminile de avarie aprinse?","answers":["Luminile intermitente de avertizare ale autobuzelor școlare vă obligă să opriți","Circulați cu atenție sporită","Nu aveți nicio obligație"],"correctIndices":[1],"correct":1,"explanation":"În situația în care întâlniți un autobuz școlar care oprește, indiferent dacă are sau nu luminile de avarie aprinse, trebuie să circulați cu atenție sporită deoarece copii sunt imprevizibili și pot traversa fără să se asigure. Legislația rutieră din România nu obligă la oprire în această situație. Dacă șoferul autobuzului școlar pune în funcțiune luminile de avarie, o face pentru a avertiza ceilalți participanți la trafic că acesta constituie un pericol pentru ceilalți participanți la trafic, iar din punct de vedere al conduitei preventive se recomandă reducerea vitezei și sporirea atenției.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0087.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0087.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 87; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 86 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-atunci-cand-un-autobuz-scolar-opreste-cu-luminile-de-avarie-aprinse","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"86","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0088","batch":"02","category":"Categoria B","question":"În cazul implicării într-un accident, puteți părăsi locul acestuia fără încuviințarea poliției, dacă a rezultat vătămarea integrității corporale a unei persoane?","answers":["Da, dacă accidentul nu s-a produs din vina dvs.","Da, în cazul în care autoturismul dvs. nu a fost avariat","Nu"],"correctIndices":[2],"correct":2,"explanation":"Dacă ați fost implicat într-un accident de circulație în urmă căruia a rezultat moartea sau vătămarea integrității corporale ori a sănătății unei persoane sunteți obligatsă anunțați imediat polițiala numărul național unic pentru apeluri de urgență 112,să nu modificați sau să ștergeți urmele accidentului,fiindu-vă interzis să părăsiți locul fapteifără încuviințarea poliției sau a procurorului care efectuează cercetarea. Nerespectarea interdicției de a părăsi locul fapteieste considerată infracțiuneși se pedepsește cuînchisoarea de la 2 la 7 ani, caz în care se dispune reținerea permisului de conducere în vederea anulării acestuia și se eliberează o dovadă înlocuitoare fără drept de circulație. Cu toate acestea,NUconstituie infracțiunesituația în care,în lipsa altor mijloace de transport, conducătorul vehiculului implicat în accident transportă el însuși persoana rănită la cel mai apropiat spital,acesta având obligațiade a declara datele personale de identitate și numărul de înmatriculare sau înregistrare a vehiculului condus, date ce se vor consemna într-un registru special, și de a se reîntoarce imediat la locul accidentului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0088.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0088.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 88; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 87 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-cazul-implicarii-intr-un-accident-puteti-parasi-locul-acestuia-fara-incuviintarea-politiei-daca-a-rezultat-vatamarea-integritatii-corpora","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"87","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0089","batch":"02","category":"Categoria B","question":"În această situație, pe lângă luminile de întâlnire trebuie să folosiți:","answers":["Luminile de ceață","Luminile de drum","Semnalizatoarele în funcțiune"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de autovehicul este obligat ca pe timp de ceață densă să folosească luminile de întâlnire împreună cu luminile de ceață, indiferent dacă circulă pe timp de zi sau de noapte. Luminile de ceață la care face referire această obligație sunt luminile de culoare roșie de la partea din spate a autovehiculului. Sunt cazuri în care autovehiculele sunt dotate cu lumini de ceață și la partea din față, acestea se mai numesc „proiectoare” iar folosirea acestora nu este obligatorie. Atât dotarea cu proiectoare cât și folosirea acestora este opțională. Trebuie știut că este interzisă folosirea luminilor de ceață în alte condiții decât pe timp de ceață. Această interzicere se aplică atât pentru luminile de ceață de culoare roșie de la partea din spate cât și pentru proiectoarele de la partea din față. Prin urmare, în această situație aveți obligația de a folosi luminile de întâlnire împreună cu luminile de ceață, iar dacă autovehiculul este dotat și proiectoare, este recomandat să le folosiți și pe acestea, mai ales pe timp de noapte. Folosirea luminilor de ceață în alte condiții decât pe timp de ceață se sancționează cu amenda prevăzută în clasa a II-a de sancțiuni și cu aplicarea a 3 puncte de penalizare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0089.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0089.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 89; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum acoperit de ceață, cu vizibilitate redusă, având un vehicul în fața sa. Șoferul trebuie să păstreze o distanță de siguranță față de vehiculul din față și să utilizeze luminile de ceață pentru a fi vizibil.","needsImageReview":true,"source":"RoDrive · ID 88 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-aceasta-situatie-pe-langa-luminile-de-intalnire-trebuie-sa-folositi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"88","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_90.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0090","batch":"02","category":"Categoria B","question":"Ce este bine să aveți în vedere pentru evitarea unui pericol, în situația din imagine?","answers":["Copiii circulă corect pe trecerea de pietoni","Copiii se pot întoarce alergând pe trecerea de pietoni, fără motiv sesizabil","Copiii urmăresc cu atenție circulația și se comportă ca atare"],"correctIndices":[1],"correct":1,"explanation":"Pietonii au anumite obligații si interziceri atunci când sunt angajați în traversarea drumului public, ca de exemplu, le este interzis să se oprească ori să se întoarcă pe trecerile pentru pietoni care nu sunt prevăzute cu semafoare. Chiar și cu aceste obligații de partea pietonilor, în cazurile în care printre pietonii cărora le acordați prioritate de trecere se află și copii, pentru evitarea unui pericol, trebuie să sporiți atenția și să aveți în vedere că aceștia se pot întoarce alergând pe trecerea de pietoni, fără un motiv sesizabil.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0090.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0090.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 90; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere de pietoni într-o zonă urbană aglomerată. Șoferul oprește pentru a acorda prioritate pietonilor care traversează strada pe trecerea marcată. O din pietonii care traversează sunt copii, care pot să fie imprevizibili.","needsImageReview":true,"source":"RoDrive · ID 89 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-este-bine-sa-aveti-in-vedere-pentru-evitarea-unui-pericol-in-situatia-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"89","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_91.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0091","batch":"02","category":"Categoria B","question":"În ce ordine vor intra autovehiculele în intersecție?","answers":["Motocicleta, autocamionul, autoturismul","Motocicleta, autoturismul, autocamionul","Autocamionul, motocicleta, autoturismul"],"correctIndices":[0],"correct":0,"explanation":"Intersecția din imagine este dirijată prin indicatoare de reglementare de prioritate. Autoturismul și autocamionul vin de pe drumuri fără prioritate și trebuie să îi acorde prioritate de trecere motocicletei. Deci pe drumul cu prioritate circulă motocicleta, întâlnind indicatorul “Drum cu prioritate” și va intra prima în intersecție. Între autoturism și autocamion s-a creat o situație de egalitate, situație în care se va aplica regula priorității de dreapta. Autoturismul îi va acorda prioritate de trecere autocamionului, deoarece virând către stânga, acesta îi vine din partea dreaptă. Ordinea de trecere este urmatoarea: prima va trece motocicleta, al doilea va trece autocamionul iar ultimul prin această intersecție va trece autoturismul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0091.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0091.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 91; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea reprezintă o intersecție în cruce, văzută de sus, în care sunt implicate trei vehicule: o motocicletă (sus), un autoturism roșu (stânga) și un camion albastru (dreapta). În dreapta motocicletei se află indicator galbene în formă de romb, semnalizând drum prioritar pentru motocicletă. În fața autoturismului este un indicator 'Cedează trecerea', iar în fața camionului este un indicator 'STOP'. Intențiile de deplasare sunt: motocicleta merge înainte, autoturismul virează la stânga, iar camionul virează la stânga. trebuie să acorde prioritate motocicletei, dar se află în situație de egalitate cu autoturismul, aplicându-se regula priorității de dreapta.","needsImageReview":true,"source":"RoDrive · ID 90 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-intra-autovehiculele-in-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"90","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_92.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0092","batch":"02","category":"Categoria B","question":"Cum procedați în situația în care semnalul roșu al semaforului este în funcțiune, iar polițistul vă adresează semnalul de a trece?","answers":["Așteptați apariția semnalului de culoare verde, care vă permite să circulați cu autovehiculul prin intersecție","Atrageți atenția polițistului că există neconcordanță între semnalul său și cel al semaforului","Respectați semnalul polițistului"],"correctIndices":[2],"correct":2,"explanation":"Participanții la trafic trebuie să respecte regulile de circulație, semnalele, indicațiile și dispozițiile polițistului rutier, precum și semnificația diferitelor tipuri de mijloace de semnalizare rutieră, în următoarea ordine de prioritate: Semnalele, indicațiile și dispozițiile polițistului rutier se vor respecta cu prioritate indiferent de situație. Deci în situația în care polițistul rutier vă adresează un semnal de trecere, sunteți obligat să respectați semnalul adresat de acesta, chiar dacă semaforul indică culoarea roșie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0092.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0092.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 92; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 91 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-situatia-in-care-semnalul-rosu-al-semaforului-este-in-functiune-iar-politistul-va-adreseaza-semnalul-de-a-trece","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"91","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0093","batch":"02","category":"Categoria B","question":"Dacă semnalul verde este însoțit de un indicator „Înainte sau la dreapta“, conducătorului de vehicul îi este permis să circule:","answers":["În toate direcțiile, deoarece semnalele luminoase primează asupra semnalizării rutiere","Numai la stânga","Numai înainte sau la dreapta"],"correctIndices":[2],"correct":2,"explanation":"Atunci când urmează să pătrundeți într-o intersecție la culoarea verde a semaforului trebuie să respectați și semnificația indicatoarelor instalate la intrarea în intersecție, cu excepția indicatoarelor de reglementare de prioritate care se vor respecta doar atunci când semafoarele nu funcționează sau atunci când semafoarele au în funcțiune semnalul cu lumină de culoare galbenă intermitentă. Atunci când întâlniți indicatorul „Înainte sau la dreapta” iar semaforul se află pe culoarea verde, aveți obligația de a respecta și semnificația indicatorului de obligare. În această situație veți circula doar pe direcțiile înainte sau la dreapta, virajul către stânga fiind interzis.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0093.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0093.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 93; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 92 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/daca-semnalul-verde-este-insotit-de-un-indicator-inainte-sau-la-dreapta-conducatorului-de-vehicul-ii-este-permis-sa-circule","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"92","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0094","batch":"02","category":"Categoria B","question":"Ce trebuie să aveți în vedere atunci când intenționați să depășiți atât bicicliști, cât și grupuri de pietoni care se deplasează pe carosabil?","answers":["Puteți depăși numai după ce pietonii și bicicliștii v-au făcut semn în acest sens","Respectați prevederile legale","Bicicliștii și pietonii pot fi depășiți numai dacă distanța laterală este de 3 m"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră nu prevede nimic în acest sens. Când intenționați să depășiți bicicliști sau grupuri de pietoni care se deplasează pe carosabil, veți respecta prevederile legale cu privire la depășire, deoarece prioritatea se acordă tuturor vehiculelor și pietonilor care au acest drept. În cazul în care grupul de pietoni este un grup organizat, deși nu se specifică acest lucru, aveți obligația să circulați cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților atunci când aceștia se află pe partea carosabilă a drumurilor cu o singură bandă de circulație pe sens. Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încălcarea sau trecerea peste acest marcaj cu linie contin","imageUrl":"/nivel-1/quiz-images/rodrive-all/0094.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0094.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 94; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 93 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-aveti-in-vedere-atunci-cand-intentionati-sa-depasiti-atat-biciclisti-cat-si-grupuri-de-pietoni-care-se-deplaseaza-pe-carosabil","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"93","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0095","batch":"02","category":"Categoria B","question":"Ce obligații revin conducătorilor de vehicule la trecerea autovehiculelor cu regim de circulație prioritară, care au în funcțiune mijloacele speciale de avertizare luminoasă de culoare albastră și pe cele de avertizare sonoră?","answers":["Să reducă viteza, să circule cât mai aproape de marginea drumului în sensul de deplasare și să acorde prioritate de trecere","Să mărească viteza pentru a nu incomoda circulația","Să oprească imediat, pe acostament sau, în lipsa acestuia, cât mai aproape de marginea drumului sau de bordura trotuarului, în sensul de deplasare"],"correctIndices":[0],"correct":0,"explanation":"Semnalele speciale de avertizare cu lumină deculoare ALBASTRĂ, împreună cu cele sonore, vă obligă să acordați prioritate de trecere, iar pentru a acorda prioritate de trecere trebuie să reduceți viteza de deplasare și să circulați cât mai aproape de marginea drumului, în sensul de deplasare, mai exact cât mai aproape de bordura ori de acostamentul din partea dreaptă. În cazul în care, pentru acordarea de prioritate, este nevoie să și opriți, trebuie să o faceți. Un exemplu bun ar fi intersecțiile în care este nevoie de oprire pentru a putea acorda prioritate de trecere acestor autovehicule cu regim de circulație prioritară. Trebuie știut că acestor autovehicule cu regim de circulație prioritară le este permis să folosească semnalele luminoase fără a fi însoțite de cele sonore, în funcție de natura misiunii ori de condițiile de trafic, situație în care autovehiculul respectiv nu are regim de circulație prioritară. Dar situația inversă, să folosească doar semnalele sonore, fără a fi însoțite de cele luminoase, nu le este permisă. Varianta B este incorectă, deoarece viteza de deplasare nu trebuie mărită, ci trebuie redusă, conform articolelor din legislația rutieră actualizată la zi, ce se găsesc în această pagina, puțin mai jos Varianta C este incorectă, deoarece oprirea imediată, pe acostament sau, în lipsa acestuia, cât mai aproape de marginea drumului sau de bordura trotuarului, în sensul de deplasare, este obligatorie la semnalele speciale de avertizare cu lumină de culoareROȘIE, împreună cu cele sonore. În cazul de față întrebarea se referă la autovehiculele care au în f","imageUrl":"/nivel-1/quiz-images/rodrive-all/0095.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0095.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 95; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 94 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-revin-conducatorilor-de-vehicule-la-trecerea-autovehiculelor-cu-regim-de-circulatie-prioritara-care-au-in-functiune-mijloacele-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"94","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0096","batch":"02","category":"Categoria B","question":"Cauzele ce pot determina creșterea nivelului de ulei în baia de ungere sunt:","answers":["Circulația frecventă pe drumuri neasfaltate","Pătrunderea apei sau a combustibilului în baia de ulei","Defectarea pompei de ulei"],"correctIndices":[1],"correct":1,"explanation":"Cauzele ce pot determina creșterea nivelului de ulei în baia de ulei pot fi: pătrunderea apei (lichidului de răcire al motorului) sau a combustibilului în baia de ulei. Circulația frecventă pe drumuri neasfaltate sau denivelate ori nu determină creștere a nivelului uleiului în baia de ulei. Defectarea pompei de ulei face ca uleiul să nu mai circule prin motor, această defecțiune nu determină creșterea nivelului de ulei în baia de ungere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0096.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0096.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 96; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 95 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cauzele-ce-pot-determina-cresterea-nivelului-de-ulei-in-baia-de-ungere-sunt","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"95","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0097","batch":"02","category":"Categoria B","question":"Indicatorul semnifică:","answers":["Sfârșitul interzicerii de a depăși","Sfârșitul tuturor restricțiilor","Interzicerea depășirii autovehiculelor, cu excepția motocicletelor fără ataș"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește \"Sfârșitul interzicerii de a depăși\" și anunță terminarea sectorului de drum pe care depășirea a fost interzisă prin indicatorul \"Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă\" sau prin indicatorul \"Depășirea interzisă autovehiculelor destinate transportului de mărfuri\". După întâlnirea indicatorului \"Sfârșitul interzicerii de a depăși\" manevra de depășire vă este permisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0097.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0097.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 97; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul circular alb, cu o linie diagonală neagră și două mașini negre, una lângă alta, arată sfârșitul interdicției de depășire.","needsImageReview":true,"source":"RoDrive · ID 96 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"96","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_98.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0098","batch":"02","category":"Categoria B","question":"Autoturismul staționează regulamentar?","answers":["Da, deoarece în zonă nu sunt restricții de circulație","Nu, deoarece se află pe un drum național","Nu, deoarece obligă camionul la depășirea prin triplare"],"correctIndices":[0],"correct":0,"explanation":"Autoturismul este staționat parțial în afara părții carosabile, fără a bloca circulația și fără a fi prezent un indicator care să interzică oprirea sau staționarea. Întrucât drumul este marcat corespunzător și vizibilitatea este bună, iar vehiculul nu reprezintă un pericol sau obstacol, staționarea este considerată regulamentară conform legislației rutiere. Faptul că autobuzul semnalizează intenția de depășire nu modifică legalitatea staționării autoturismului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0098.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0098.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 98; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație pe un drum unde un autobuz semnalizează intenția de a depăși un camion. Autoturismul albastru din sensul opus este staționat parțial în afara părții carosabile, dar lăsând spațiu astfel încât să poată fi depășit, astfel nu blochează circulația. Indicatorul arată o limită de viteză de 80 km/h.","needsImageReview":true,"source":"RoDrive · ID 97 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autoturismul-stationeaza-regulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"97","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_99.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0099","batch":"02","category":"Categoria B","question":"Se poate efectua depășirea în situația dată?","answers":["Da, legea nu interzice","Da, deoarece din sens opus nu se apropie niciun vehicul","Nu, deoarece vă aflați în curbă"],"correctIndices":[2],"correct":2,"explanation":"În această situație intenționați să depășiți și vă aflați într-o curbă în care marcajul de separare a sensurilor de circulație este o linie continuă. Iar în curbe sau când în urma depășirii se încalcă marcajul longitudinal continuu, se interzice depășirea. Deci în această situație depășirea nu se poate efectua regulamentar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0099.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0099.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 99; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum curbat, semnalizat cu indicatoare pătratice albe, fiecare având o săgeată roșie spre dreapta, care avertizează asupra direcției curbei. În plus, pe stradă se află marcaj longitudinal continuu.","needsImageReview":true,"source":"RoDrive · ID 98 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/se-poate-efectua-depasirea-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"98","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_100.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0100","batch":"02","category":"Categoria B","question":"Cum procedați în intersecția care urmează?","answers":["Opriți și acordați prioritate pietonilor","Opriți la marcajul transversal de oprire și vă asigurați, după care virați la dreapta","Reduceți viteza și virați la dreapta"],"correctIndices":[1],"correct":1,"explanation":"În această intersecție întâlniți două indicatoare, unul de reglementare de prioritate și unul de obligare. Indicatorul de reglementare de prioritate se numește „Oprire” și vă obligă să opriți înaintea marcajului transversal de oprire aplicat pe carosabil și stând pe loc să acordați prioritate vehiculelor care circulă pe drumul transversal. Indicatorul de obligare se numește „La dreapta” și vă obligă să virați pe prima stradă la dreapta. Prin urmare, în această intersecție opriți înaintea marcajului transversal de oprire, acordați prioritate și apoi virați către dreapta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0100.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0100.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 100; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicatorul octogonal roșu pe care scrie cu alb 'STOP' și un indicator adițional circular albastru, cu o săgeată albă spre dreapta, care obligă virajul la dreapta. La intersecție este prezentă o trecere de pietoni cu marcaj transversal, care indică unde trebuie să oprească mașina cât timp așteaptă să pătrundă în intersectie.","needsImageReview":true,"source":"RoDrive · ID 99 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-intersectia-care-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"99","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_101.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
